css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); display: flex; justify-content: space-between; }
.loader span { position: relative; width: calc(var(--loader-size) * .04); background: linear-gradient(color-mix(in srgb, var(--accent) 30%, transparent), transparent); border-radius: 3px; transform-origin: 50% 0; }
.loader span::after { content: ''; position: absolute; bottom: 0; left: 50%; width: calc(var(--loader-size) * .13); height: calc(var(--loader-size) * .13); margin-left: calc(var(--loader-size) * -.065); border-radius: 50%; background: var(--accent); }
.loader span:nth-child(even)::after { background: var(--accent-2); }
.loader span:nth-child(1) { height: 100%; animation: pw calc(var(--loader-speed) * 2) ease-in-out infinite; }
.loader span:nth-child(2) { height: 90%; animation: pw calc(var(--loader-speed) * 1.86) ease-in-out infinite; }
.loader span:nth-child(3) { height: 80%; animation: pw calc(var(--loader-speed) * 1.72) ease-in-out infinite; }
.loader span:nth-child(4) { height: 70%; animation: pw calc(var(--loader-speed) * 1.58) ease-in-out infinite; }
.loader span:nth-child(5) { height: 60%; animation: pw calc(var(--loader-speed) * 1.44) ease-in-out infinite; }
@keyframes pw { 0%, 100% { transform: rotate(30deg); } 50% { transform: rotate(-30deg); } }
